+#define QCOM_JPEG_QUALITY_DEF	98
+#define QCOM_JPEG_QUALITY_MAX	100
+#define QCOM_JPEG_QUALITY_UNT	1
+
+#define QCOM_JPEG_FPS_MIN	1
